le')==='operator')>Operator / Driver</option><option value="vehicle_owner" @selected(old('role')==='vehicle_owner')>Vehicle owner</option></select></div><div class="col-md-6"><label class="form-label">Email address</label><input name="email" type="email" class="form-control" value="{{ old('email') }}" autocomplete="email" required></div><div class="col-md-6"><label class="form-label">Mobile number</label><input name="mobile_number" class="form-control" value="{{ old('mobile_number') }}" placeholder="09171234567" autocomplete="tel" required></div><div class="col-12"><label class="form-label">Address</label><textarea name="address" class="form-control" rows="2" required>{{ old('address') }}</textarea></div><div class="col-md-6"><label class="form-label">Password</label><div class="input-group"><input id="password" name="password" type="password" class="form-control" autocomplete="new-password" required><button type="button" class="btn btn-light border" onclick="togglePassword('password', this)" title="Show password"><i class="bi bi-eye"></i></button></div></div><div class="col-md-6"><label class="form-label">Confirm password</label><div class="input-group"><input id="password_confirmation" name="password_confirmation" type="password" class="form-control" autocomplete="new-password" required><button type="button" class="btn btn-light border" onclick="togglePassword('password_confirmation', this)" title="Show password"><i class="bi bi-eye"></i></button></div></div></div><div class="form-check mt-4"><input class="form-check-input" type="checkbox" name="terms" value="1" id="terms" @checked(old('terms')) required><label class="form-check-label small" for="terms">I agree to the <a href="#terms">Terms and Conditions</a>.</label></div><div class="form-check mt-2"><input class="form-check-input" type="checkbox" name="privacy" value="1" id="privacy" @checked(old('privacy')) required><label class="form-check-label small" for="privacy">I acknowledge the <a href="#privacy">Privacy Policy</a>.</label></div><button class="btn btn-primary w-100 py-2 mt-4">Create account <i class="bi bi-arrow-right ms-2"></i></button></form><p class="login-note">Already have an account? <a href="{{ route('login') }}">Sign in</a></p></div></div><script>function togglePassword(id,button){const input=document.getElementById(id);const visible=input.type==='text';input.type=visible?'password':'text';button.querySelector('i').className=visible?'bi bi-eye':'bi bi-eye-slash';button.title=visible?'Show password':'Hide password';}</script></body></html>
